import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
    ['user_message']: validateUserMessage,
    ['ping']: validatePingMessage,
    ['list_sessions']: validateListSessionsMessage,
    ['list_conversations']: validateListConversationsMessage,
  };
  const selected = validator[message.type];
  return selected ? selected(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if ('limit' in message && !isProtocolLimit(limit)) {
    return {valid: false, error: 'list_sessions limit must be an integer from 1 to 200'};
  }

  if (!('before' in message)) {
    return {valid: true, data: {type: 'list_sessions', limit: limit as number | undefined}};
  }

  if (!isCursor(message.before)) {
    return {valid: false, error: 'list_sessions before must be a valid cursor'};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit: limit as number | undefined,
      before: message.before,
    },
  };
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if ('limit' in message && !isProtocolLimit(limit)) {
    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
  }

  if (!('before' in message)) {
    return limit === undefined
      ? {valid: true, data: {type: 'list_conversations'}}
      : {valid: true, data: {type: 'list_conversations', limit}};
  }

  if (!isConversationCursor(message.before)) {
    return {valid: false, error: 'list_conversations before must be a valid cursor'};
  }

  return {
    valid: true,
    data: {
      type: 'list_conversations',
      limit: limit as number | undefined,
      before: message.before,
    },
  };
}

function isProtocolLimit(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 1 && value <= 200;
}

function isCursor(value: unknown): value is {updatedAt: string | number; sessionId: string} {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const cursor = value as Record<string, unknown>;
  if (typeof cursor.sessionId !== 'string' || cursor.sessionId.length < 1 || cursor.sessionId.length > 128)
    return false;

  if (typeof cursor.updatedAt === 'string') return !Number.isNaN(Date.parse(cursor.updatedAt));
  return (
    typeof cursor.updatedAt === 'number' &&
    Number.isFinite(cursor.updatedAt) &&
    !Number.isNaN(new Date(cursor.updatedAt).getTime())
  );
}

function isConversationCursor(value: unknown): value is {updatedAt: string; sessionId: string} {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const cursor = value as Record<string, unknown>;
  return (
    typeof cursor.sessionId === 'string' &&
    cursor.sessionId.length >= 1 &&
    cursor.sessionId.length <= 128 &&
    typeof cursor.updatedAt === 'string' &&
    !Number.isNaN(Date.parse(cursor.updatedAt))
  );
}
